-- Curriculum lessons 145-162 of 324

begin;
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-css-intermediate-01","course_id":"css-intermediate","title":"معماری CSS با لایه‌های آبشاری","slug":"css-intermediate-01","summary":"لایه‌های آبشاری ترتیب اولویت گروه‌های قانون را مستقل از specificity کنترل می‌کنند؛ برای معماری بزرگ، لایه‌ها از انباشتن انتخابگرهای سنگین قابل نگهداری‌ترند.","content_html":"<h3>هدف درس</h3><p>لایه‌های آبشاری ترتیب اولویت گروه‌های قانون را مستقل از specificity کنترل می‌کنند؛ برای معماری بزرگ، لایه‌ها از انباشتن انتخابگرهای سنگین قابل نگهداری‌ترند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@layer reset, base, components, utilities;\n@layer base { h1 { margin: 0; color: #1f2937; } }\n@layer components { .notice { padding: 1rem; border: 1px solid; } }\n@layer utilities { .text-center { text-align: center; } }</code></pre><h3>تمرین</h3><p>یک فایل CSS با چهار لایه بساز و یک قانون متعارض را در دو لایه قرار بده؛ نتیجه را با ترتیب لایه‌ها توضیح بده.</p><h3>نکته فنی</h3><p>ترتیب لایه‌ها برای قواعد مهم است؛ specificity به‌تنهایی برنده را تعیین نمی‌کند.</p><h3>معیار موفقیت</h3><p>قواعد در لایه درست قرار بگیرند و اثر ترتیب لایه‌ها مستند شود.</p>","starter_code":"@layer reset, base, components, utilities;\n@layer base { h1 { margin: 0; color: #1f2937; } }\n@layer components { .notice { padding: 1rem; border: 1px solid; } }\n@layer utilities { .text-center { text-align: center; } }","exercise":"یک فایل CSS با چهار لایه بساز و یک قانون متعارض را در دو لایه قرار بده؛ نتیجه را با ترتیب لایه‌ها توضیح بده.","status":"published","sort_order":1,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-02","course_id":"css-intermediate","title":"محدودسازی دامنه سبک‌ها با @scope","slug":"css-intermediate-02","summary":"@scope دامنه اثر انتخابگرها را به یک زیر درخت محدود می‌کند و از نشت سبک مؤلفه‌ها به بخش‌های دیگر می‌کاهد.","content_html":"<h3>هدف درس</h3><p>@scope دامنه اثر انتخابگرها را به یک زیر درخت محدود می‌کند و از نشت سبک مؤلفه‌ها به بخش‌های دیگر می‌کاهد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@scope (.profile-card) {\n  h2 { color: #174ea6; }\n  a { text-decoration-thickness: .12em; }\n}</code></pre><h3>تمرین</h3><p>دو کارت با کلاس‌های متفاوت بساز؛ سبک scoped را فقط به کارت پروفایل محدود کن و تفاوت را آزمایش کن.</p><h3>نکته فنی</h3><p>@scope جایگزین کامل معماری مؤلفه یا Shadow DOM نیست؛ پشتیبانی مرورگر را بررسی کن.</p><h3>معیار موفقیت</h3><p>سبک‌های داخل scope بیرون از دامنه اثر نگذارند.</p>","starter_code":"@scope (.profile-card) {\n  h2 { color: #174ea6; }\n  a { text-decoration-thickness: .12em; }\n}","exercise":"دو کارت با کلاس‌های متفاوت بساز؛ سبک scoped را فقط به کارت پروفایل محدود کن و تفاوت را آزمایش کن.","status":"published","sort_order":2,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-03","course_id":"css-intermediate","title":"CSS Nesting و ساختار تو‌در‌تو","slug":"css-intermediate-03","summary":"CSS Nesting اجازه می‌دهد قواعد مرتبط درون انتخابگر والد نوشته شوند و ساختار مؤلفه خواناتر شود.","content_html":"<h3>هدف درس</h3><p>CSS Nesting اجازه می‌دهد قواعد مرتبط درون انتخابگر والد نوشته شوند و ساختار مؤلفه خواناتر شود.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.menu {\n  color: #222;\n  &amp; a { color: inherit; }\n  &amp;:hover { background: #eef2ff; }\n}</code></pre><h3>تمرین</h3><p>یک کارت با حالت hover و پیوند داخلی بساز؛ نسخه nested و نسخه تخت را مقایسه کن.</p><h3>نکته فنی</h3><p>در nesting از & برای رابطه دقیق استفاده کن و از تو‌در‌تویی عمیق بپرهیز.</p><h3>معیار موفقیت</h3><p>نسخه nested همان نتیجه مورد انتظار را بدهد و خوانا بماند.</p>","starter_code":".menu {\n  color: #222;\n  & a { color: inherit; }\n  &:hover { background: #eef2ff; }\n}","exercise":"یک کارت با حالت hover و پیوند داخلی بساز؛ نسخه nested و نسخه تخت را مقایسه کن.","status":"published","sort_order":3,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-04","course_id":"css-intermediate","title":"انتخابگرهای پیشرفته :is و :where","slug":"css-intermediate-04","summary":":is و :where چند انتخابگر را گروه‌بندی می‌کنند؛ :where specificity صفر دارد و برای پایه‌های قابل بازنویسی مناسب است.","content_html":"<h3>هدف درس</h3><p>:is و :where چند انتخابگر را گروه‌بندی می‌کنند؛ :where specificity صفر دارد و برای پایه‌های قابل بازنویسی مناسب است.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:where(header, footer) a { color: #174ea6; }\n:is(h1, h2, h3).title { font-family: sans-serif; }</code></pre><h3>تمرین</h3><p>یک گروه قانون پایه با :where بساز و آن را با یک کلاس ساده بازنویسی کن؛ specificity دو روش را مقایسه کن.</p><h3>نکته فنی</h3><p>:is specificity بیشترین آرگومان را می‌گیرد؛ :where همیشه صفر است.</p><h3>معیار موفقیت</h3><p>بتوانی علت برنده‌شدن قانون را با specificity توضیح بدهی.</p>","starter_code":":where(header, footer) a { color: #174ea6; }\n:is(h1, h2, h3).title { font-family: sans-serif; }","exercise":"یک گروه قانون پایه با :where بساز و آن را با یک کلاس ساده بازنویسی کن؛ specificity دو روش را مقایسه کن.","status":"published","sort_order":4,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-05","course_id":"css-intermediate","title":"انتخابگر رابطه‌ای :has","slug":"css-intermediate-05","summary":":has انتخابگر والد‌مانند است و می‌تواند بر اساس وجود فرزند یا همسایه، ظاهر عنصر را تغییر دهد.","content_html":"<h3>هدف درس</h3><p>:has انتخابگر والد‌مانند است و می‌تواند بر اساس وجود فرزند یا همسایه، ظاهر عنصر را تغییر دهد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.field:has(input:invalid) { border-inline-start: 4px solid #b42318; }\n.card:has(&gt; img) { display: grid; }</code></pre><h3>تمرین</h3><p>کارت دارای تصویر و کارت بدون تصویر بساز؛ فقط کارت دارای تصویر را سبک بده و حالت ورودی نامعتبر را هم آزمایش کن.</p><h3>نکته فنی</h3><p>:has را با انتخابگرهای محدود و دقیق به کار ببر؛ برای فهرست‌های بسیار بزرگ اثر عملکرد را بسنج.</p><h3>معیار موفقیت</h3><p>قانون فقط در حالت وجود فرزند موردنظر فعال شود.</p>","starter_code":".field:has(input:invalid) { border-inline-start: 4px solid #b42318; }\n.card:has(> img) { display: grid; }","exercise":"کارت دارای تصویر و کارت بدون تصویر بساز؛ فقط کارت دارای تصویر را سبک بده و حالت ورودی نامعتبر را هم آزمایش کن.","status":"published","sort_order":5,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-06","course_id":"css-intermediate","title":"انتخابگرهای ساختاری با nth-child of","slug":"css-intermediate-06","summary":"nth-child می‌تواند با بخش of فقط میان فرزندانی که با انتخابگر مشخص تطبیق دارند شمارش کند.","content_html":"<h3>هدف درس</h3><p>nth-child می‌تواند با بخش of فقط میان فرزندانی که با انتخابگر مشخص تطبیق دارند شمارش کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.list &gt; :nth-child(odd of .item) { background: #f1f5f9; }\n.list &gt; :nth-child(3n of li.active) { font-weight: 700; }</code></pre><h3>تمرین</h3><p>فهرستی از item و تبلیغ بساز و سومین عضو فعال را بدون شمردن تبلیغ‌ها هدف بگیر.</p><h3>نکته فنی</h3><p>تفاوت nth-child با nth-of-type و فیلتر of را دقیق بررسی کن.</p><h3>معیار موفقیت</h3><p>فقط عضو مطابق موقعیت فیلترشده انتخاب شود.</p>","starter_code":".list > :nth-child(odd of .item) { background: #f1f5f9; }\n.list > :nth-child(3n of li.active) { font-weight: 700; }","exercise":"فهرستی از item و تبلیغ بساز و سومین عضو فعال را بدون شمردن تبلیغ‌ها هدف بگیر.","status":"published","sort_order":6,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-07","course_id":"css-intermediate","title":"انتخابگر ویژگی با تطبیق دقیق","slug":"css-intermediate-07","summary":"انتخابگر ویژگی می‌تواند وجود، برابری، شروع، پایان یا شامل‌شدن یک رشته را بررسی کند.","content_html":"<h3>هدف درس</h3><p>انتخابگر ویژگی می‌تواند وجود، برابری، شروع، پایان یا شامل‌شدن یک رشته را بررسی کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>a[href^=\"https://\"] { text-decoration: underline; }\ninput[aria-invalid=\"true\"] { border-color: #b42318; }\nimg[alt=\"\"] { outline: 1px dashed #999; }</code></pre><h3>تمرین</h3><p>برای پیوند خارجی، ورودی نامعتبر و فایل PDF سه انتخابگر ویژگی بنویس.</p><h3>نکته فنی</h3><p>تطبیق رشته‌ای به مقدار واقعی attribute وابسته است و جای اعتبارسنجی معنایی را نمی‌گیرد.</p><h3>معیار موفقیت</h3><p>هر انتخابگر فقط عنصرهای موردنظر را هدف بگیرد.</p>","starter_code":"a[href^=\"https://\"] { text-decoration: underline; }\ninput[aria-invalid=\"true\"] { border-color: #b42318; }\nimg[alt=\"\"] { outline: 1px dashed #999; }","exercise":"برای پیوند خارجی، ورودی نامعتبر و فایل PDF سه انتخابگر ویژگی بنویس.","status":"published","sort_order":7,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-08","course_id":"css-intermediate","title":"ویژگی‌های منطقی برای چیدمان چندجهته","slug":"css-intermediate-08","summary":"ویژگی‌های منطقی مانند margin-inline و padding-block با جهت نوشتار و writing mode سازگارند و نیاز به چپ/راست ثابت را کاهش می‌دهند.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های منطقی مانند margin-inline و padding-block با جهت نوشتار و writing mode سازگارند و نیاز به چپ/راست ثابت را کاهش می‌دهند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.panel { padding-block: 1rem; padding-inline: 1.5rem; border-inline-start: 4px solid #2563eb; }\n.title { margin-block-end: .75rem; }</code></pre><h3>تمرین</h3><p>یک مؤلفه فارسی و انگلیسی بساز؛ با تغییر dir بررسی کن فاصله‌ها و مرز منطقی درست جابه‌جا شوند.</p><h3>نکته فنی</h3><p>برای رابط‌های چندزبانه از left و right ثابت فقط وقتی واقعاً لازم است استفاده کن.</p><h3>معیار موفقیت</h3><p>با تغییر جهت، چیدمان بدون بازنویسی قوانین درست بماند.</p>","starter_code":".panel { padding-block: 1rem; padding-inline: 1.5rem; border-inline-start: 4px solid #2563eb; }\n.title { margin-block-end: .75rem; }","exercise":"یک مؤلفه فارسی و انگلیسی بساز؛ با تغییر dir بررسی کن فاصله‌ها و مرز منطقی درست جابه‌جا شوند.","status":"published","sort_order":8,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-09","course_id":"css-intermediate","title":"مدیریت writing-mode و متن عمودی","slug":"css-intermediate-09","summary":"writing-mode جهت جریان متن و محورهای نوشتاری را تغییر می‌دهد؛ ویژگی‌های منطقی در کنار آن رفتار سازگارتر دارند.","content_html":"<h3>هدف درس</h3><p>writing-mode جهت جریان متن و محورهای نوشتاری را تغییر می‌دهد؛ ویژگی‌های منطقی در کنار آن رفتار سازگارتر دارند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.vertical-label { writing-mode: vertical-rl; text-orientation: mixed; }\n.caption { writing-mode: horizontal-tb; }</code></pre><h3>تمرین</h3><p>یک برچسب عمودی کنار کارت بساز و متن فارسی و لاتین را آزمایش کن.</p><h3>نکته فنی</h3><p>writing-mode صرفاً چرخاندن جعبه نیست؛ جریان و محورهای چیدمان را تغییر می‌دهد.</p><h3>معیار موفقیت</h3><p>متن عمودی خوانا باشد و محتوای اصلی همچنان در جریان منطقی قرار گیرد.</p>","starter_code":".vertical-label { writing-mode: vertical-rl; text-orientation: mixed; }\n.caption { writing-mode: horizontal-tb; }","exercise":"یک برچسب عمودی کنار کارت بساز و متن فارسی و لاتین را آزمایش کن.","status":"published","sort_order":9,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-10","course_id":"css-intermediate","title":"تعریف قرارداد طراحی با custom properties","slug":"css-intermediate-10","summary":"custom properties قراردادهای طراحی را در یک نقطه متمرکز می‌کنند و با var در اجزای مختلف مصرف می‌شوند.","content_html":"<h3>هدف درس</h3><p>custom properties قراردادهای طراحی را در یک نقطه متمرکز می‌کنند و با var در اجزای مختلف مصرف می‌شوند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --color-brand: #174ea6; --space-card: 1.25rem; --radius-card: .8rem; }\n.card { color: var(--color-brand); padding: var(--space-card); border-radius: var(--radius-card); }</code></pre><h3>تمرین</h3><p>برای رنگ، فاصله و شعاع گوشه‌ها توکن تعریف کن و سه مؤلفه را فقط با توکن‌ها سبک بده.</p><h3>نکته فنی</h3><p>نام متغیر باید معنایی باشد؛ مقدار ثابت تکراری را بی‌هدف به متغیر تبدیل نکن.</p><h3>معیار موفقیت</h3><p>تغییر یک توکن، همه مؤلفه‌های وابسته را هماهنگ به‌روزرسانی کند.</p>","starter_code":":root { --color-brand: #174ea6; --space-card: 1.25rem; --radius-card: .8rem; }\n.card { color: var(--color-brand); padding: var(--space-card); border-radius: var(--radius-card); }","exercise":"برای رنگ، فاصله و شعاع گوشه‌ها توکن تعریف کن و سه مؤلفه را فقط با توکن‌ها سبک بده.","status":"published","sort_order":10,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-11","course_id":"css-intermediate","title":"ثبت نوع متغیر با @property","slug":"css-intermediate-11","summary":"@property نوع و رفتار custom property را ثبت می‌کند؛ این کار می‌تواند مقدار اولیه و قابلیت انیمیشن نوع‌دار را مشخص کند.","content_html":"<h3>هدف درس</h3><p>@property نوع و رفتار custom property را ثبت می‌کند؛ این کار می‌تواند مقدار اولیه و قابلیت انیمیشن نوع‌دار را مشخص کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@property --progress {\n  syntax: \"&lt;percentage&gt;\";\n  inherits: false;\n  initial-value: 0%;\n}\n.bar { width: var(--progress); }</code></pre><h3>تمرین</h3><p>یک متغیر درصدی ثبت کن و مقدار نامعتبر را آزمایش کن؛ تفاوت آن را با custom property ثبت‌نشده توضیح بده.</p><h3>نکته فنی</h3><p>syntax و initial-value باید با هم سازگار باشند و پشتیبانی مرورگر بررسی شود.</p><h3>معیار موفقیت</h3><p>مقدار متغیر مطابق نوع ثبت‌شده پردازش شود.</p>","starter_code":"@property --progress {\n  syntax: \"<percentage>\";\n  inherits: false;\n  initial-value: 0%;\n}\n.bar { width: var(--progress); }","exercise":"یک متغیر درصدی ثبت کن و مقدار نامعتبر را آزمایش کن؛ تفاوت آن را با custom property ثبت‌نشده توضیح بده.","status":"published","sort_order":11,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-12","course_id":"css-intermediate","title":"ساخت تم پویا با متغیرهای وابسته","slug":"css-intermediate-12","summary":"تم پویا با تغییر مجموعه توکن‌ها ساخته می‌شود؛ بهتر است رنگ معنایی مانند surface و text تعریف شود نه رنگ وابسته به نام مؤلفه.","content_html":"<h3>هدف درس</h3><p>تم پویا با تغییر مجموعه توکن‌ها ساخته می‌شود؛ بهتر است رنگ معنایی مانند surface و text تعریف شود نه رنگ وابسته به نام مؤلفه.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --surface: white; --text: #172033; }\n[data-theme=\"dark\"] { --surface: #172033; --text: #f8fafc; }\nbody { background: var(--surface); color: var(--text); }</code></pre><h3>تمرین</h3><p>تم روشن و تاریک بساز و سه مؤلفه را با توکن‌های معنایی هماهنگ کن.</p><h3>نکته فنی</h3><p>کنتراست هر تم باید جداگانه بررسی شود؛ وارونه‌کردن رنگ‌ها به‌تنهایی کافی نیست.</p><h3>معیار موفقیت</h3><p>هر دو تم خوانا باشند و تغییر data-theme ظاهر همه مؤلفه‌ها را تغییر دهد.</p>","starter_code":":root { --surface: white; --text: #172033; }\n[data-theme=\"dark\"] { --surface: #172033; --text: #f8fafc; }\nbody { background: var(--surface); color: var(--text); }","exercise":"تم روشن و تاریک بساز و سه مؤلفه را با توکن‌های معنایی هماهنگ کن.","status":"published","sort_order":12,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-13","course_id":"css-intermediate","title":"رنگ‌های مدرن با oklch و color-mix","slug":"css-intermediate-13","summary":"OKLCH رنگ را با روشنایی، کروما و فام توصیف می‌کند و color-mix امکان ترکیب رنگ در فضای مشخص را می‌دهد.","content_html":"<h3>هدف درس</h3><p>OKLCH رنگ را با روشنایی، کروما و فام توصیف می‌کند و color-mix امکان ترکیب رنگ در فضای مشخص را می‌دهد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --brand: oklch(55% .18 250); }\n.button { background: var(--brand); }\n.button:hover { background: color-mix(in oklch, var(--brand), black 12%); }</code></pre><h3>تمرین</h3><p>یک رنگ برند در OKLCH تعریف کن و برای hover با color-mix نسخه تیره‌تر بساز؛ تفاوت ادراکی را مشاهده کن.</p><h3>نکته فنی</h3><p>نمایشگر و مرورگر ممکن است gamut متفاوت داشته باشند؛ خروجی نهایی را روی دستگاه واقعی بررسی کن.</p><h3>معیار موفقیت</h3><p>رنگ پایه و حالت hover هماهنگ و خوانا باشند.</p>","starter_code":":root { --brand: oklch(55% .18 250); }\n.button { background: var(--brand); }\n.button:hover { background: color-mix(in oklch, var(--brand), black 12%); }","exercise":"یک رنگ برند در OKLCH تعریف کن و برای hover با color-mix نسخه تیره‌تر بساز؛ تفاوت ادراکی را مشاهده کن.","status":"published","sort_order":13,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-14","course_id":"css-intermediate","title":"شفافیت و ترکیب رنگ‌های نسبی","slug":"css-intermediate-14","summary":"رنگ‌های نسبی می‌توانند از یک رنگ پایه کانال‌ها را استخراج و تغییر دهند؛ برای ساخت طیف منسجم مفیدند.","content_html":"<h3>هدف درس</h3><p>رنگ‌های نسبی می‌توانند از یک رنگ پایه کانال‌ها را استخراج و تغییر دهند؛ برای ساخت طیف منسجم مفیدند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --brand: oklch(60% .16 250); }\n.badge { background: oklch(from var(--brand) calc(l + .25) c h); color: oklch(from var(--brand) .2 .02 h); }</code></pre><h3>تمرین</h3><p>از یک رنگ پایه، نسخه روشن و تیره بساز و کنتراست متن روی هرکدام را بررسی کن.</p><h3>نکته فنی</h3><p>نحو رنگ نسبی جدید است؛ برای پروژه واقعی fallback و پشتیبانی مرورگر را بررسی کن.</p><h3>معیار موفقیت</h3><p>نسخه‌های رنگی از رنگ پایه مشتق شوند و کنتراست مناسب داشته باشند.</p>","starter_code":":root { --brand: oklch(60% .16 250); }\n.badge { background: oklch(from var(--brand) calc(l + .25) c h); color: oklch(from var(--brand) .2 .02 h); }","exercise":"از یک رنگ پایه، نسخه روشن و تیره بساز و کنتراست متن روی هرکدام را بررسی کن.","status":"published","sort_order":14,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-15","course_id":"css-intermediate","title":"مدیریت gamut و رنگ نمایشگر","slug":"css-intermediate-15","summary":"رنگ خارج از gamut نمایشگر ممکن است نگاشت شود؛ انتخاب فضای رنگ و fallback روی خروجی نهایی اثر دارد.","content_html":"<h3>هدف درس</h3><p>رنگ خارج از gamut نمایشگر ممکن است نگاشت شود؛ انتخاب فضای رنگ و fallback روی خروجی نهایی اثر دارد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --brand-fallback: #2563eb; --brand-wide: color(display-p3 0.1 0.35 0.9); }\n.button { background: var(--brand-fallback); background: var(--brand-wide); }</code></pre><h3>تمرین</h3><p>یک رنگ fallback و یک رنگ wide-gamut تعریف کن و با ابزار توسعه‌دهنده بررسی کن کدام مرورگر کدام مقدار را می‌پذیرد.</p><h3>نکته فنی</h3><p>رنگ گسترده‌تر تضمین نمی‌کند همه نمایشگرها آن را یکسان نشان دهند.</p><h3>معیار موفقیت</h3><p>در مرورگر فاقد پشتیبانی، fallback معتبر باقی بماند.</p>","starter_code":":root { --brand-fallback: #2563eb; --brand-wide: color(display-p3 0.1 0.35 0.9); }\n.button { background: var(--brand-fallback); background: var(--brand-wide); }","exercise":"یک رنگ fallback و یک رنگ wide-gamut تعریف کن و با ابزار توسعه‌دهنده بررسی کن کدام مرورگر کدام مقدار را می‌پذیرد.","status":"published","sort_order":15,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-16","course_id":"css-intermediate","title":"ماسک‌کردن لایه‌ها با mask","slug":"css-intermediate-16","summary":"mask با کانال آلفا یا روشنایی بخش‌هایی از عنصر را آشکار یا پنهان می‌کند و برای جلوه‌های تصویری کاربرد دارد.","content_html":"<h3>هدف درس</h3><p>mask با کانال آلفا یا روشنایی بخش‌هایی از عنصر را آشکار یا پنهان می‌کند و برای جلوه‌های تصویری کاربرد دارد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.avatar { mask-image: linear-gradient(to bottom, black 70%, transparent); }\n.logo { -webkit-mask-image: url(\"shape.svg\"); mask-image: url(\"shape.svg\"); }</code></pre><h3>تمرین</h3><p>تصویری را با ماسک گرادیانی محو کن و نسخه بدون mask را به‌عنوان fallback نگه دار.</p><h3>نکته فنی</h3><p>محتوای ضروری را فقط با ماسک یا تصویر پس‌زمینه منتقل نکن.</p><h3>معیار موفقیت</h3><p>تصویر در حالت پشتیبانی و عدم پشتیبانی قابل فهم باقی بماند.</p>","starter_code":".avatar { mask-image: linear-gradient(to bottom, black 70%, transparent); }\n.logo { -webkit-mask-image: url(\"shape.svg\"); mask-image: url(\"shape.svg\"); }","exercise":"تصویری را با ماسک گرادیانی محو کن و نسخه بدون mask را به‌عنوان fallback نگه دار.","status":"published","sort_order":16,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-17","course_id":"css-intermediate","title":"برش شکل‌ها با clip-path","slug":"css-intermediate-17","summary":"clip-path ناحیه قابل مشاهده عنصر را به شکل مشخص محدود می‌کند و برای ساخت قاب‌های هندسی مفید است.","content_html":"<h3>هدف درس</h3><p>clip-path ناحیه قابل مشاهده عنصر را به شکل مشخص محدود می‌کند و برای ساخت قاب‌های هندسی مفید است.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.thumbnail { clip-path: polygon(0 0, 100% 0, 88% 100%, 0 100%); }\n.avatar { clip-path: circle(48%); }</code></pre><h3>تمرین</h3><p>یک تصویر کارت را با polygon برش بده و نسخه دایره‌ای بساز؛ متن جایگزین و اندازه تصویر را حفظ کن.</p><h3>نکته فنی</h3><p>clip-path فقط نمایش را برش می‌دهد؛ فضای چیدمان عنصر همچنان مستطیلی است.</p><h3>معیار موفقیت</h3><p>برش بصری بدون حذف اطلاعات ضروری انجام شود.</p>","starter_code":".thumbnail { clip-path: polygon(0 0, 100% 0, 88% 100%, 0 100%); }\n.avatar { clip-path: circle(48%); }","exercise":"یک تصویر کارت را با polygon برش بده و نسخه دایره‌ای بساز؛ متن جایگزین و اندازه تصویر را حفظ کن.","status":"published","sort_order":17,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-18","course_id":"css-intermediate","title":"ترکیب لایه‌ها با blend modes","slug":"css-intermediate-18","summary":"blend modes نحوه ترکیب رنگ یک لایه با زمینه را تعیین می‌کنند و باید با پس‌زمینه واقعی آزمایش شوند.","content_html":"<h3>هدف درس</h3><p>blend modes نحوه ترکیب رنگ یک لایه با زمینه را تعیین می‌کنند و باید با پس‌زمینه واقعی آزمایش شوند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.hero { background: linear-gradient(#102a43aa,#102a43aa), url(\"hero.jpg\") center/cover; background-blend-mode: multiply; }\n.icon { mix-blend-mode: screen; }</code></pre><h3>تمرین</h3><p>یک تصویر قهرمان با overlay بساز و تفاوت background-blend-mode و mix-blend-mode را بررسی کن.</p><h3>نکته فنی</h3><p>ترکیب رنگ می‌تواند کنتراست متن را کاهش دهد؛ خوانایی را آزمایش کن.</p><h3>معیار موفقیت</h3><p>متن روی تصویر در حالت‌های مختلف همچنان خوانا بماند.</p>","starter_code":".hero { background: linear-gradient(#102a43aa,#102a43aa), url(\"hero.jpg\") center/cover; background-blend-mode: multiply; }\n.icon { mix-blend-mode: screen; }","exercise":"یک تصویر قهرمان با overlay بساز و تفاوت background-blend-mode و mix-blend-mode را بررسی کن.","status":"published","sort_order":18,"estimated_minutes":40}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();
commit;
